package com.oshi.messenger.network.v2.devsync

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * __DEVSYNC_DIRECT_2026_09_22__ The shared own-device-sync core against the golden vectors in
 * docs/fixtures/devsync/ (generated by the independent Python reference `devsync_ref.py`).
 * OSHI-Desktop runs the identical check (`com.oshi.desktop.devsync.DevSyncVectorsTest`).
 */
class DevSyncVectorsTest {

    @Test
    fun goldenVectors_allMatch() {
        val report = DevSyncVectorCheck.runAll()
        println("devsync vectors: " + report.toString().lineSequence().first())
        assertEquals(report.toString(), 0, report.failures)
        assertTrue("suspiciously few checks: ${report.passes}", report.passes > 150)
    }

    @Test
    fun wrongAccount_cannotCompleteMessage1_andSasMatchesOnBothSides() {
        val ikA = ByteArray(32) { 1 }
        val ikB = ByteArray(32) { 2 }
        val dkI = DevSyncCrypto.randomBytes(32)
        val dkR = DevSyncCrypto.randomBytes(32)
        val pro = DevSyncKeys.prologue(DevSyncKeys.TRANSPORT_LAN)
        val i = NoiseHandshake(true, dkI, DevSyncKeys.psk(ikA), pro)
        val stranger = NoiseHandshake(false, dkR, DevSyncKeys.psk(ikB), pro)
        val m1 = i.writeMessage1(DevSyncSession.MSG1_PAYLOAD)
        val refused = runCatching { stranger.readMessage1(m1) }.isFailure
        assertTrue("a device of another account must not read message 1", refused)

        val i2 = NoiseHandshake(true, dkI, DevSyncKeys.psk(ikA), pro)
        val r2 = NoiseHandshake(false, dkR, DevSyncKeys.psk(ikA), pro)
        r2.readMessage1(i2.writeMessage1(DevSyncSession.MSG1_PAYLOAD))
        i2.readMessage2(r2.writeMessage2("{}".toByteArray()))
        r2.readMessage3(i2.writeMessage3("{}".toByteArray()))
        assertEquals(DevSyncKeys.sasCode(i2.handshakeHash), DevSyncKeys.sasCode(r2.handshakeHash))
        assertEquals(DevSyncKeys.deviceIdHex(DevSyncCrypto.x25519Public(dkR)), DevSyncKeys.deviceIdHex(i2.remoteStatic!!))
    }
}
